function validate([n, relations]) {
  if (!Number.isInteger(n) || n < 1 || n > 5000) return 'n is between 1 and 5000.';
  if (!Array.isArray(relations) || relations.length < 1 || relations.length > 5000) return 'relations needs 1 to 5000 pairs.';
  const seen = new Set();
  for (const pair of relations) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each relation is a pair [prevCourse, nextCourse].';
    const [a, b] = pair;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 1 || a > n || b < 1 || b > n) return 'Courses are numbered 1 to n.';
    if (a === b) return 'A course cannot be its own prerequisite.';
    const key = a + ',' + b;
    if (seen.has(key)) return 'Each relation appears only once.';
    seen.add(key);
  }
  return null;
}

