function minimumSemesters(n, relations) {
  const graph = Array.from({ length: n + 1 }, () => []);
  const indegree = new Array(n + 1).fill(0);
  for (const [prevCourse, nextCourse] of relations) {
    graph[prevCourse].push(nextCourse);
    indegree[nextCourse]++;
  }
  let queue = [];
  for (let course = 1; course <= n; course++) {
    if (indegree[course] === 0) {
      queue.push(course);
    }
  }
  let semesters = 0;
  let taken = 0;
  while (queue.length > 0) {
    semesters++;
    const nextQueue = [];
    for (const course of queue) {
      taken++;
      for (const dependent of graph[course]) {
        indegree[dependent]--;
        if (indegree[dependent] === 0) {
          nextQueue.push(dependent);
        }
      }
    }
    queue = nextQueue;
  }
  return taken === n ? semesters : -1;
}

