function minimumSemesters(n, relations) {
  const done = new Array(n + 1).fill(false);
  let finished = 0;
  let semesters = 0;
  while (finished < n) {
    const ready = [];
    for (let c = 1; c <= n; c++) {
      if (done[c]) continue;
      if (relations.every(([p, q]) => q !== c || done[p])) ready.push(c);
    }
    if (ready.length === 0) return -1;
    for (const c of ready) done[c] = true;
    finished += ready.length;
    semesters++;
  }
  return semesters;
}

