function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(1000, 2000) : int(2, 8);
  const maxPairs = n * (n - 1);
  const target = large ? int(1200, 1990) : int(1, Math.min(maxPairs, 12));
  const order = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
  const seen = new Set();
  const relations = [];
  const add = (a, b) => {
    const key = a * 10000 + b;
    if (a === b || seen.has(key)) return;
    seen.add(key);
    relations.push([a, b]);
  };
  const acyclic = rand() < (large ? 0.75 : 0.5);
  if (large) {
    // A backbone chain gives a long answer; a closing edge makes a cycle.
    const length = int(2, Math.min(n, 600));
    for (let i = 0; i + 1 < length; i++) add(order[i], order[i + 1]);
    if (!acyclic) add(order[length - 1], order[0]);
  }
  for (let tries = 0; relations.length < target && tries < 20000; tries++) {
    let i = Math.floor(rand() * n), j = Math.floor(rand() * n);
    if (acyclic && i > j) [i, j] = [j, i];
    add(order[i], order[j]);
  }
  for (let i = relations.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [relations[i], relations[j]] = [relations[j], relations[i]]; }
  return [n, relations];
}
